function validate([heights]) {
  if (!Array.isArray(heights) || heights.length < 1 || heights.length > 100) return 'heights needs 1 to 100 values.';
  if (heights.some(h => !Number.isInteger(h) || h < 1 || h > 100)) return 'Each height is a whole number from 1 to 100.';
  return null;
}

