function heightChecker(heights) {
  // Position i of the sorted row holds the value v with (#values < v) <= i < (#values <= v).
  let wrong = 0;
  for (let i = 0; i < heights.length; i++) {
    const v = heights.find(h => {
      const below = heights.filter(x => x < h).length;
      const upTo = heights.filter(x => x <= h).length;
      return below <= i && i < upTo;
    });
    if (v !== heights[i]) wrong++;
  }
  return wrong;
}

