function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(80, 100) : pick(1, 8);
  const top = rand() < 0.4 ? pick(1, 4) : 100;
  const heights = Array.from({ length: n }, () => pick(1, top));
  // Sometimes start from a sorted row and disturb it with a few swaps.
  if (rand() < 0.4) {
    heights.sort((a, b) => a - b);
    const swaps = pick(0, 3);
    for (let s = 0; s < swaps; s++) {
      const a = pick(0, n - 1);
      const b = pick(0, n - 1);
      [heights[a], heights[b]] = [heights[b], heights[a]];
    }
  }
  return [heights];
}
